// What we make together on the island (the two paintings, the gallery wall,
// the willow's decorations and the photo wall) lives in the database, one
// hidden widgets row each, so it's the same for both of us on every device
// and never depends on a phone's small local storage. A copy is kept on the
// device only so the island opens fast (and works offline).
const SHARED = ["tdd3d.painting.0", "tdd3d.painting.1", "tdd3d.gallery", "tdd3d.tree", "tdd3d.album", "tdd3d.bakery", "tdd3d.garden", "tdd3d.pantry", "tdd3d.vases", "tdd3d.flowers"];
const PREFIX = "__prefs:game:shared:";
const CACHE = "tdd3dShared:";
const OLD_STAMPS = "tdd3dSyncStamps";

export const isShared = (key) => SHARED.includes(key);
const rowId = (key) => PREFIX + key.slice("tdd3d.".length);
const bridge = () => window.__tddBridge;

// per key: value (the same string the island always stored), at (when it last
// changed), base (the database's copy we last saw), dirty (needs sending up)
const state = new Map();
const listeners = new Set();
let loaded = false;
let pushTimer = 0;

function readCache(key) {
  try {
    const c = JSON.parse(localStorage.getItem(CACHE + key) || "null");
    if (c && typeof c === "object" && typeof c.v === "string") return { value: c.v, at: Number(c.at) || 0, base: Number(c.base) || 0, dirty: Boolean(c.d) };
  } catch {}
  return null;
}
function writeCache(key) {
  const st = state.get(key);
  try {
    if (st.value == null) localStorage.removeItem(CACHE + key);
    else localStorage.setItem(CACHE + key, JSON.stringify({ v: st.value, at: st.at, base: st.base, d: st.dirty ? 1 : 0 }));
  } catch {
    // too big for this device: the database still has it
    try {
      localStorage.removeItem(CACHE + key);
    } catch {}
  }
}
// saved before this existed: the old copy on this device, with when it was written
function readOld(key) {
  let value = null;
  let at = 0;
  try {
    value = localStorage.getItem(key) ?? (key === "tdd3d.painting.0" ? localStorage.getItem("tdd3d.painting") : null);
    at = Number(JSON.parse(localStorage.getItem(OLD_STAMPS) || "{}")?.[key]) || 1;
  } catch {}
  return value == null ? null : { value, at, base: 0, dirty: false };
}
function forgetOld(key) {
  try {
    localStorage.removeItem(key);
    if (key === "tdd3d.painting.0") localStorage.removeItem("tdd3d.painting");
  } catch {}
}

// fresh: this device had nothing saved, so whatever it makes before it has seen the database
// (a blank garden, a new day's wish) must never replace what's there
for (const key of SHARED) state.set(key, readCache(key) || readOld(key) || { value: null, at: 0, base: 0, dirty: false, fresh: true });

export function getShared(key) {
  return state.get(key)?.value ?? null;
}

export function setShared(key, value) {
  const st = state.get(key);
  if (!st || st.value === value) return;
  st.value = value;
  st.at = Math.max(Date.now(), st.at + 1);
  st.dirty = true;
  writeCache(key);
  schedulePush(1500);
}

// called with (key, value) when a newer copy arrives from the database
export function onShared(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

// a copy from the old per-person backup: used if it's newer than this device's
export function offerShared(key, value, at) {
  const st = state.get(key);
  if (!st || st.base || typeof value !== "string" || !(at > st.at)) return;
  st.value = value;
  st.at = at;
}

// safe to drop from the old per-person backup once the database has it
export const sharedSaved = (key) => Boolean(state.get(key)?.base) && !state.get(key)?.dirty;

export async function pullShared() {
  const sb = bridge()?.supabase;
  if (!sb || !bridge()?.getUser?.()) return;
  const { data, error } = await sb.from("widgets").select("id,data").like("id", `${PREFIX}%`);
  if (error) throw error;
  const rows = new Map((data || []).map((r) => [r.id, r.data]));
  for (const key of SHARED) {
    const st = state.get(key);
    const d = rows.get(rowId(key));
    const cloud = d && typeof d.v === "string" ? { value: d.v, at: Number(d.at) || 0 } : null;
    // this device's copy wins only if it's newer and (once it has seen the
    // database) nobody else changed the database since
    const mine = st.value != null && (!cloud || (!st.fresh && (st.base ? st.base === cloud.at && st.at > cloud.at : st.at > cloud.at)));
    st.fresh = false;
    if (mine) st.dirty = true;
    else if (cloud) {
      const changed = cloud.value !== st.value;
      Object.assign(st, { value: cloud.value, at: cloud.at, base: cloud.at, dirty: false });
      writeCache(key);
      forgetOld(key);
      if (changed) for (const fn of listeners) fn(key, cloud.value);
    }
  }
  if (!loaded) keepFresh();
  loaded = true;
  if ([...state.values()].some((st) => st.dirty)) await pushShared();
}

// a device left open still picks up what the other one saved (every minute, and on coming
// back to the tab), so it never carries on from an old copy
function keepFresh() {
  const again = () => {
    if (busy || document.hidden) return;
    busy = true;
    pullShared()
      .catch((error) => console.warn("island saves failed to load", error))
      .finally(() => (busy = false));
  };
  setInterval(again, 60000);
  document.addEventListener("visibilitychange", () => !document.hidden && again());
}
let busy = false;

// someone else saved this since we last looked: theirs stands, and the island shows it
function takeCloud(key, d) {
  const st = state.get(key);
  const cloud = { value: d.v, at: Number(d.at) || 0 };
  const changed = cloud.value !== st.value;
  Object.assign(st, { value: cloud.value, at: cloud.at, base: cloud.at, dirty: false });
  writeCache(key);
  if (changed) for (const fn of listeners) fn(key, cloud.value);
}

async function pushShared() {
  pushTimer = 0;
  const sb = bridge()?.supabase;
  const uid = bridge()?.getUser?.()?.id;
  if (!sb || !uid) return;
  if (!loaded) {
    // see what's in the database before changing it
    try {
      await pullShared();
    } catch (error) {
      console.warn("island save failed", error);
      schedulePush(8000);
    }
    return;
  }
  let failed = false;
  for (const key of SHARED) {
    const st = state.get(key);
    if (!st.dirty || st.value == null) continue;
    const at = st.at;
    const now = new Date().toISOString();
    const payload = { title: "__prefs", side: "left", x: 0, y: 0, content: null, updated_at: now, data: { v: st.value, at, by: uid } };
    try {
      // only over the copy we last saw: never over something newer from the other device
      let q = sb.from("widgets").update(payload).eq("id", rowId(key));
      if (st.base) q = q.eq("data->>at", String(st.base));
      const { data: rows, error } = await q.select("id");
      if (error) throw error;
      if (!rows?.length) {
        const { data: cur, error: readError } = await sb.from("widgets").select("data").eq("id", rowId(key)).maybeSingle();
        if (readError) throw readError;
        if (cur?.data && typeof cur.data.v === "string") {
          takeCloud(key, cur.data);
          continue;
        }
        const { error: insertError } = await sb.from("widgets").insert({ id: rowId(key), ...payload });
        if (insertError) throw insertError;
      }
      st.base = at;
      // changed again while it was on its way: send that too
      if (st.at === at) st.dirty = false;
      writeCache(key);
      forgetOld(key);
    } catch (error) {
      console.warn("island save failed", error);
      failed = true;
    }
  }
  if (failed || [...state.values()].some((st) => st.dirty)) schedulePush(failed ? 8000 : 1500);
}

function schedulePush(ms) {
  clearTimeout(pushTimer);
  pushTimer = setTimeout(() => void pushShared(), ms);
}

// send anything waiting before the page goes away
export function flushShared() {
  if (!pushTimer) return;
  clearTimeout(pushTimer);
  void pushShared();
}

// a picture small enough to keep: webp where the browser can make it (iPhones
// can't, and their PNGs are huge), otherwise a jpeg; the canvases are opaque
export function compactImage(canvas, quality = 0.85) {
  const webp = canvas.toDataURL("image/webp", quality);
  return webp.startsWith("data:image/webp") ? webp : canvas.toDataURL("image/jpeg", Math.min(0.92, quality + 0.05));
}
