// Visitor links: a temporary link for friends who aren't on the site.
// Visitors can walk around and say hi, but can't open, change, post or
// save anything. Each link has its own code and an end time; we keep the
// codes we made (and share them with each other) so we can check visitors.
const KEY = "tdd3d.guestTokens";

export function parseGuest(search = location.search) {
  const raw = new URLSearchParams(search).get("guest");
  if (!raw) return null;
  const [token, exp36] = raw.split(".");
  const exp = parseInt(exp36 || "", 36);
  if (!/^[a-z0-9]{10,40}$/i.test(token || "") || !exp) return { bad: true };
  return { token, exp, expired: Date.now() > exp };
}

export function loadTokens() {
  try {
    const list = JSON.parse(localStorage.getItem(KEY) || "[]") || [];
    return list.filter((t) => t && t.t && t.exp > Date.now());
  } catch {
    return [];
  }
}
function saveTokens(list) {
  try {
    localStorage.setItem(KEY, JSON.stringify(list));
  } catch {}
}

export function makeToken(hours) {
  const bytes = new Uint8Array(12);
  crypto.getRandomValues(bytes);
  const t = [...bytes].map((b) => b.toString(36).padStart(2, "0")).join("").slice(0, 20);
  const exp = Date.now() + hours * 3600 * 1000;
  const list = loadTokens();
  list.push({ t, exp });
  saveTokens(list);
  return { t, exp };
}

export function mergeTokens(list, revoked = []) {
  const mine = loadTokens().filter((x) => !revoked.includes(x.t));
  for (const t of list || []) if (t?.t && t.exp > Date.now() && !mine.some((x) => x.t === t.t) && !revoked.includes(t.t)) mine.push(t);
  saveTokens(mine);
  return mine;
}

export function revokeAll() {
  const list = loadTokens();
  saveTokens([]);
  return list.map((t) => t.t);
}

export function validToken(t) {
  return loadTokens().some((x) => x.t === t);
}

export function guestLink({ t, exp }) {
  return `${location.origin}${location.pathname}?mode=3d&guest=${t}.${exp.toString(36)}`;
}

export const WORLD_CHANNEL = "tdd3d-world";

// Before the world opens, asks whoever is on the island whether this link is
// still good (a link can be ended early). Resolves "denied", or "ok" when no
// one says no in time.
export function checkGuest(token, supabase, wait = 2500) {
  return new Promise((resolve) => {
    if (!supabase) return resolve("ok");
    const key = `guest-${token}:check${Math.random().toString(36).slice(2, 8)}`;
    const ch = supabase.channel(WORLD_CHANNEL, { config: { broadcast: { self: false } } });
    let done = false;
    let ping = 0;
    const finish = (verdict) => {
      if (done) return;
      done = true;
      clearInterval(ping);
      supabase.removeChannel(ch);
      resolve(verdict);
    };
    ch.on("broadcast", { event: "x" }, ({ payload }) => {
      if (payload?.t === "deny" && payload.to === key) finish("denied");
    });
    ch.subscribe((status) => {
      if (status === "SUBSCRIBED") {
        const hello = () => ch.send({ type: "broadcast", event: "state", payload: { key } }).catch?.(() => {});
        hello();
        ping = setInterval(hello, 800);
        setTimeout(() => finish("ok"), wait);
      } else if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") finish("ok");
    });
    setTimeout(() => finish("ok"), wait + 5000);
  });
}
